python3 -I -S -B - <<'P26_EXACT_DEPLOYMENT'
ARCHIVE_B64 = ''
ARCHIVE_BYTES = 23120
ARCHIVE_SHA = 'a09bee33121a1d0503ea297818aa4f7b1f597c79f0ced130ecaa94a8f32078fa'
STAGE = '/workspace/p26-cell05-all-row-gaps-20261127-v1'
WORKFLOW_SHA = '8f7a4623f798fcb45391c6daea05536c59f21d906a3c08c7517600ae2b0f4b22'
DRIVER = '/workspace/p26-cell05-all-row-gaps-20261127-v1/tools/p26/cell05-all-row-gaps-20261127/run_gaps.py'
import base64, hashlib, io, json, os, tarfile
from pathlib import Path, PurePosixPath
body = base64.b64decode(ARCHIVE_B64, validate=True)
assert len(body) == ARCHIVE_BYTES and hashlib.sha256(body).hexdigest() == ARCHIVE_SHA
with tarfile.open(fileobj=io.BytesIO(body), mode='r:xz') as tar:
    entries = tar.getmembers()
    assert len(entries) == len({m.name for m in entries})
    contents = {}
    for m in entries:
        q = PurePosixPath(m.name)
        assert m.isfile() and not q.is_absolute() and '..' not in q.parts
        contents[m.name] = tar.extractfile(m).read()
    index = json.loads(contents['DEPLOYMENT_CONTENTS.json'])
    assert index['stage'] == STAGE and index['workflow']['sha256'] == WORKFLOW_SHA
    rows = {r['member']: r for r in index['files']}
    assert len(rows) == len(index['files']) and set(contents) == set(rows) | {'DEPLOYMENT_CONTENTS.json'}
    for name, row in rows.items():
        data = contents[name]
        assert len(data) == row['bytes'] and hashlib.sha256(data).hexdigest() == row['sha256']
    for name, data in contents.items():
        target = Path(STAGE) / name
        for parent in target.parents:
            assert not parent.is_symlink(), str(parent)
        assert not target.is_symlink()
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            assert target.is_file() and target.read_bytes() == data, 'Existing deployed file differs: ' + str(target)
        else:
            with target.open('xb') as out:
                out.write(data)
        assert target.read_bytes() == data
print(json.dumps({'status':'EXACT_WORKFLOW_DEPLOYED','files':len(rows),'archive_sha256':ARCHIVE_SHA,'workflow_sha256':WORKFLOW_SHA}), flush=True)
python = '/opt/codex/runtimes/codex-primary-runtime/dependencies/python/bin/python3'
os.execv(python, [python, '-I', '-S', '-B', DRIVER, 'preflight', '--workflow-sha256', WORKFLOW_SHA])

P26_EXACT_DEPLOYMENT
